// This Rust library provides a fast implementation of the Fibonacci sequence,
// which is a series of numbers where each number is the sum of the two preceding ones,
// usually starting with 0 and 1. The function `fib` is optimized for efficiency,
// especially for large values of `n`.

/// Computes the n-th Fibonacci number.
/// 
/// # Examples
/// 
/// ```
/// assert_eq!(fib(10), 55);
/// assert_eq!(fib(1), 1);
/// assert_eq!(fib(2), 1);
/// assert_eq!(fib(3), 2);
/// assert_eq!(fib(4), 3);
/// assert_eq!(fib(5), 5);
/// assert_eq!(fib(6), 8);
/// assert_eq!(fib(7), 13);
/// assert_eq!(fib(8), 21);
/// assert_eq!(fib(9), 34);
/// ```
fn fib(n: u32) -> u64 {
    if n <= 1 {
        return n;
    }
    let (a, b) = (0, 1);
    for _ in 2..=n {
        let next = a + b;
        a = b;
        b = next;
    }
    next
}

// A simple check function to verify the correctness of the `fib` function.
fn check_fibonacci() {
    assert_eq!(fib(10), 55);
    assert_eq!(fib(1), 1);
    assert_eq!(fib(2), 1);
    assert_eq!(fib(3), 2);
    assert_eq!(fib(4), 3);
    assert_eq!(fib(5), 5);
    assert_eq!(fib(6), 8);
    assert_eq!(fib(7), 13);
    assert_eq!(fib(8), 21);
    assert_eq!(fib(9), 34);
    println!("All tests passed successfully!");
}

