/// Encodes a string into run-length encoding.
///
/// # Examples
///
/// ```
/// assert_eq!(rle("aaabcc"), "3a1b2c");
/// assert_eq!(rle(""), "");
/// ```
fn rle(input: &str) -> String {
    if input.is_empty() {
        return String::new();
    }

    let mut encoded = String::new();
    let mut count = 1;
    let mut prev_char = input.chars().next().unwrap();

    for c in input.chars() {
        if c == prev_char {
            count += 1;
        } else {
            encoded.push_str(&format!("{}{}", count, prev_char));
            count = 1;
        }
        prev_char = c;
    }

    encoded.push_str(&format!("{}{}", count, prev_char));

    encoded
}

// Function to check the correctness of the rle function
fn check() {
    assert_eq!(rle("aaabcc"), "3a1b2c");
    assert_eq!(rle(""), "");
    assert_eq!(rle("aabbcc"), "3a2b2c");
    assert_eq!(rle("abababab"), "3a3b3c");
    assert_eq!(rle("abcabcabc"), "3a4b4c4");
    println!("All tests passed successfully!");
}

