use std::collections::HashMap;

/// Counts the frequency of each word in a given text.
///
/// # Examples
///
/// ```
/// assert_eq!(word_count("Hello world!"), HashMap::from([("hello", 1), ("world", 1)]));
/// assert_eq!(word_count("Rust is fun"), HashMap::from([("rust", 1), ("is", 1), ("fun", 1)]));
/// ```
fn word_count(text: &str) -> HashMap<String, usize> {
    // Split the text into words and convert them to lowercase
    let words: Vec<&str> = text.split_whitespace().map(|s| s.to_lowercase()).collect();

    // Count the occurrences of each word
    let mut word_count = HashMap::new();
    for word in words {
        *word_count.entry(word).or_insert(0) += 1;
    }

    word_count
}

