/// Computes the greatest common divisor (GCD) of two numbers `a` and `b`.
///
/// # Examples
///
/// ```
/// assert_eq!(gcd(48, 18), 6);
/// assert_eq!(gcd(25, 15), 5);
/// ```
fn gcd(a: u64, b: u64) -> u64 {
    if a == 0 {
        return b;
    }
    if b == 0 {
        return a;
    }
    while b != 0 {
        let temp = b;
        b = a % b;
        a = temp;
    }
    a
}

// Function to check the correctness of the gcd function
fn check_gcd() {
    assert_eq!(gcd(48, 18), 6);
    assert_eq!(gcd(25, 15), 5);
    assert_eq!(gcd(0, 5), 0);
    assert_eq!(gcd(100, 80), 20);
    println!("All tests passed successfully!");
}

