/// Calculates the least common multiple (LCM) of two positive integers `a` and `b`.
/// If either number is 0, the result is 0.
///
/// # Examples
/// ```
/// assert_eq!(lcm(4, 6), 12);
/// assert_eq!(lcm(21, 6), 42);
/// assert_eq!(lcm(0, 10), 0);
/// ```
fn lcm(a: u64, b: u64) -> u64 {
    if a == 0 || b == 0 {
        0
    } else {
        (a / gcd(a, b)) * b
    }
}

/// Helper function to calculate the greatest common divisor (GCD) of two numbers.
fn gcd(a: u64, b: u64) -> u64 {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}

// Check function to verify the correctness of the `lcm` function.
fn check_lcm() {
    assert_eq!(lcm(4, 6), 12);
    assert_eq!(lcm(21, 6), 42);
    assert_eq!(lcm(0, 10), 0);
    println!("All tests passed successfully.");
}

