/// Reverses the order of words in the given string `s` and returns them as a single string.
/// Words are separated by whitespace.
///
/// # Examples
///
/// ```
/// assert_eq!(reverse_words(String::from("Hello World")), String::from("World Hello"));
/// assert_eq!(reverse_words(String::from("Rust Programming")), String::from("Programming Rust"));
/// ```
fn reverse_words(s: &str) -> String {
    s.split_whitespace().rev().collect::<Vec<String>>().join(" ")
}

