/// Checks if two strings are anagrams of each other, ignoring case and spaces.
///
/// # Examples
///
/// ```
/// assert_eq!(is_anagram("Listen", "Silent"), true);
/// assert_eq!(is_anagram("Dormitory", "Dirty room"), true);
/// assert_eq!(is_anagram("Conversation", "Voices rant on"), true);
