// Define the function to find the index of a target in a sorted slice
// The function returns the index of target in the slice, or None if it is not found
pub fn find(v: &[i32], target: i32) -> Option<usize> {
    // If the slice is empty or the target is not in the slice, return None
    if v.is_empty() || target >= v[v.len() - 1] {
        return None;
    }

    // Initialize pointers for the start and end of the slice
    let mut left = 0;
    let mut right = v.len() - 1;

    // Perform binary search
    while left <= right {
        // Calculate the middle index
        let mid = left + (right - left) / 2;

        // Check if the target is found at the middle index
        if v[mid] == target {
            return Some(mid);
        }

        // If the target is greater than the middle value, search the right half
        if v[mid] < target {
            left = mid + 1;
        } else {
            // If the target is less than the middle value, search the left half
            right = mid - 1;
        }
    }

    // If the target is not found, return None
    None
}

