/// Converts a given unsigned integer `n` to its binary representation as a string.
/// The function handles the special case where `n` is 0 by returning "0".
///
/// # Examples
///
/// ```
/// assert_eq!(to_binary(0), "0");
/// assert_eq!(to_binary(15), "1111");
/// ```
fn to_binary(n: u32) -> String {
    if n == 0 {
        return "0".to_string();
    }
    let mut binary_str = String::new();
    while n > 0 {
        binary_str = format!("1{binary_str}");
        n >>= 1;
    }
    binary_str
}

