// Define a function to convert a Roman numeral to an integer
// The function should handle the conversion of Roman numerals to integers
// It should return None if the input string is empty or contains non-roman characters
// Examples:
// >>> from_roman("II")
// Some(2)
// >>> from_roman("XIV")
// Some(46)
// >>> from_roman("LXXVI")
// Some(76)
// >>> from_roman("MMXXIV")
// Some(2224)
// >>> from_roman("")
// None
fn from_roman(s: &str) -> Option<u32> {
    if s.is_empty() {
        return None;
    }

    let mut result = 0;
    let mut i = 0;

    while i < s.len() {
        let current_char = s.chars().nth(i).unwrap();

        if current_char == 'M' {
            result += 1000;
        } else if current_char == 'D' {
            result += 500;
        } else if current_char == 'C' {
            result += 100;
        } else if current_char == 'L' {
            result += 50;
        } else if current_char == 'X' {
            result += 10;
        } else if current_char == 'V' {
            result += 5;
        } else if current_char == 'I' {
            result += 1;
        } else {
            return None;
        }

        i += 1;
    }

    Some(result)
}

// A check function to verify the correctness of the `from_roman` function
fn check() {
    assert_eq!(from_roman("II"), Some(2));
    assert_eq!(from_roman("XIV"), Some(46));
    assert_eq!(from_roman("LXXVI"), Some(76));
    assert_eq!(from_roman("MMXXIV"), Some(2224));
    assert_eq!(from_roman(""), None);
    println!("All tests passed!");
}

