/// Shifts each letter in the input string `s` forward by `shift` positions in the alphabet.
/// Wraps around and keeps case.
///
/// # Examples
///
/// ```
/// assert_eq!(shift_letters("hello", 3), "lipps");
/// assert_eq!(shift_letters("world", 5), "asvph");
/// ```
fn shift_letters(s: &str, shift: u8) -> String {
    let alphabet: Vec<char> = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'n', 'o', 'p', 'q', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z'];
    let mut result = String::new();

    for c in s.chars() {
        let index = alphabet.iter().position(|&a| a == c).unwrap_or(c);
        let new_index = (index + shift) % alphabet.len();
        result.push(alphabet[new_index]);
    }

    result
}

