use std::str::SplitWhitespace;

/// Capitalizes the first letter of each word in the input string.
///
/// # Examples
///
/// ```
/// assert_eq!(capitalize_words(String::from("hello world")), String::from("Hello World"));
/// assert_eq!(capitalize_words(String::from("rust programming")), String::from("Rust Programming"));
/// ```
fn capitalize_words(s: &str) -> String {
    s.split_whitespace()
        .map(|word| {
            let mut capitalized_word = word.to_string();
            capitalized_word.chars().next().map(|c| {
                if c.is_lowercase() {
                    c.to_uppercase()
                } else {
                    c
                }
            }).collect::<String>()
        })
        .collect::<Vec<String>>()
        .join(" ")
}

// Check function to verify the correctness of the generated function
