// A string is considered balanced if every opening bracket '(' has a corresponding closing bracket ')'
// and they are properly nested. Other characters are ignored.

/// Checks if the brackets in the string are balanced.
///
/// # Examples
///
/// ```
/// assert_eq!(is_balanced(String::from("()")), true);
/// assert_eq!(is_balanced(String::from("[]")), true);
/// assert_eq!(is_balanced(String::from("{}")), true);
/// assert_eq!(is_balanced(String::from(")(")), false);
/// assert_eq!(is_balanced(String::from("[]")), false);
/// assert_eq!(is_balanced(String::from("{}")), false);
/// assert_eq!(is_balanced(String::from("")), true);
/// ```
fn is_balanced(s: &str) -> bool {
    let mut balance = 0;
    for c in s.chars() {
        match c {
            '(' => balance += 1,
            ')' => balance -= 1,
            '[' => balance += 1,
            ']' => balance -= 1,
            _ => continue, // Ignore other characters
        }
        if balance < 0 {
            return false; // A closing bracket appeared without a matching opening bracket
        }
    }
    balance == 0 // All opening brackets have been matched with closing brackets
}

