// This Rust library defines a function that calculates the median of a given slice of f64 numbers.
// The median is the middle value in a sorted list of numbers. If the slice is empty, it returns None.
// The function uses Rust's built-in sorting and the median calculation.

/// Calculates the median of a slice of f64 numbers.
/// If the slice is empty, returns None.
///
/// # Examples
///
/// ```
/// assert_eq!(median(&[3.0, 1.0, 2.0]), Some(2.0));
/// assert_eq!(median(&[1.0, 2.0, 3.0]), Some(2.0));
/// assert_eq!(median(&[4.0]), Some(4.0));
/// assert_eq!(median(&[]), None);
/// ```
fn median(v: &[f64]) -> Option<f64> {
    if v.is_empty() {
        return None;
    }

    let mut sorted_v = v.to_vec();
    sorted_v.sort_unstable();

    let n = sorted_v.len();
    if n % 2 == 0 {
        // If the count is even, return the average of the two middle elements.
        let mid1 = sorted_v[n / 2 - 1];
        let mid2 = sorted_v[n / 2];
        Some((mid1 + mid2) / 2.0)
    } else {
        // If the count is odd, return the middle element.
        Some(sorted_v[n / 2])
    }
}

// A simple check function to verify the correctness of the median function.
fn check_median() {
    assert_eq!(median(&[3.0, 1.0, 2.0]), Some(2.0));
    assert_eq!(median(&[1.0, 2.0, 3.0]), Some(2.0));
    assert_eq!(median(&[4.0]), Some(4.0));
    assert_eq!(median(&[]), None);
    println!("All tests passed successfully!");
}

