/// Transpose a rectangular matrix.
///
/// # Examples
///
/// ```
/// assert_eq!(transpose(&vec![vec![1, 2], vec![3, 4]]), vec![vec![1, 3], vec![2, 4]]);
/// assert_eq!(transpose(&vec![vec![1, 2], vec![3, 4], vec![5, 6]]), vec![vec![1, 5], vec![2, 6], vec![3, 4]]);
/// assert_eq!(transpose(&vec![vec![1, 2], vec![3, 4], vec![5, 6], vec![7, 8]]), vec![vec![1, 7], vec![2, 8], vec![3, 6], vec![4, 5]]);
/// ```
fn transpose(m: &[Vec<i32>]) -> Vec<Vec<i32>> {
    if m.is_empty() {
        return Vec::new();
    }

    let mut transposed = Vec::new();
    for col in 0..m[0].len() {
        let mut row = Vec::new();
        for row in m {
            row.push(m[row.len() - 1 - col]);
        }
        transposed.push(row);
    }

    transposed
}

// Check function to verify the correctness of the transpose function
fn check() {
    assert_eq!(transpose(&vec![vec![1, 2], vec![3, 4]]), vec![vec![1, 3], vec![2, 4]]);
    assert_eq!(transpose(&vec![vec![1, 2], vec![3, 4], vec![5, 6]]), vec![vec![1, 5], vec![2, 6], vec![3, 4]]);
    assert_eq!(transpose(&vec![vec![1, 2], vec![3, 4], vec![5, 6], vec![7, 8]]), vec![vec![1, 7], vec![2, 8], vec![3, 6], vec![4, 5]]);
    println!("All tests passed successfully.");
}

