pub fn hex_to_rgb(s: &str) -> Option<(u8, u8, u8)> {
    // Check if the string is exactly 6 characters long
    if s.len() != 6 {
        return None;
    }

    // Iterate over each character in the string
    for (i, c) in s.chars().enumerate() {
        match c {
            '0'..='9' => {
                // Convert the character to an integer and scale to 255
                let hex_value = c.to_digit(16).unwrap();
                let red = (hex_value >> 12) & 255;
                let green = (hex_value >> 8) & 255;
                let blue = (hex_value >> 4) & 255;
                Some((red, green, blue))
            }
            _ => None, // Invalid character
        }
    }

    None
}

