/// Finds the second largest distinct value in a vector.
/// If there are fewer than two distinct values, returns None.
///
/// # Examples
///
/// ```
/// assert_eq!(second_largest(vec![4, 3, 2, 1]), Some(3));
/// assert_eq!(second_largest(vec![10, 10, 10]), None);
/// assert_eq!(second_largest(vec![5]), Some(5));
/// assert_eq!(second_largest(vec![]), None);
/// ```
fn second_largest(v: &[i32]) -> Option<i32> {
    let mut unique_values: HashSet<i32> = v.iter().collect();
    let mut distinct_values: Vec<i32> = unique_values.into_iter().collect();
    distinct_values.sort_unstable();
    if distinct_values.len() < 2 {
