/// Counts the number of times a character c appears in a string s.
///
/// # Examples
///
/// ```
/// assert_eq!(count_char("hello", 'l'), 2);
/// assert_eq!(count_char("rust", 'r'), 1);
/// ```
fn count_char(s: &str, c: char) -> usize {
    s.chars().filter(|&c| c == c).count()
}

